package com.tianshu.assets.governance.infrastructure;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.tianshu.assets.asset.domain.AssetScope;import com.tianshu.assets.governance.task.application.GovernanceRuleCatalog;import com.tianshu.assets.governance.task.domain.GovernanceRuleSnapshot;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository @Profile({"local","oceanbase"}) @ConditionalOnProperty(name="asset.governance-schema-enabled",havingValue="true")
public class JdbcGovernanceRuleCatalog implements GovernanceRuleCatalog {private final JdbcClient jdbc;private final ObjectMapper json;public JdbcGovernanceRuleCatalog(JdbcClient j,ObjectMapper o){jdbc=j;json=o;}@Override public GovernanceRuleSnapshot enabledSnapshot(){return jdbc.sql("SELECT id,data_standard_id,data_standard_version,field_rule_version,dictionary_versions_json,quality_policy_id,quality_policy_version FROM governance_rule_catalog WHERE enabled=1 ORDER BY id DESC LIMIT 1").query((r,n)->new GovernanceRuleSnapshot(r.getLong("id"),r.getString("data_standard_id"),r.getLong("data_standard_version"),r.getLong("field_rule_version"),map(r.getString("dictionary_versions_json")),r.getString("quality_policy_id"),r.getLong("quality_policy_version"))).single();}@Override public List<AssetScope> validScopes(){return jdbc.sql("SELECT platform_family,product_line,base_name,production_line,process_section,platform_family,platform_variant FROM asset_scope_ext WHERE active=1 ORDER BY id").query((r,n)->new AssetScope(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7))).list();}private Map<String,Long> map(String v){try{return json.readValue(v,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException("治理规则目录数据损坏",e);}}}
